interface EvictionPolicy<K> { pick(keys: K[]): K }
const lru: EvictionPolicy<string> = { pick: (keys) => keys[0] };

class Cache<K, V, P extends EvictionPolicy<K>> {
  constructor(private readonly policy: P) {}
  victim(keys: K[]): K { return this.policy.pick(keys); }
}
const c = new Cache<string, number, typeof lru>(lru);
